// AUTO-GENERATED by scripts/build_guide.py -- do not hand-edit.
window.GUIDE = window.GUIDE || {};
window.GUIDE.bosses = [{"id":"king-slime","order":1,"era":"Pre-Hardmode","optional":true,"name":"King Slime","summon":"Slime Crown","naturalSpawn":"Small (~1%) chance any time you kill a normal Slime; guaranteed with a Slime Crown.","arena":["Flat ground with some platforms, King Slime just needs room to not get you cornered.","Not required, but any open Forest clearing works fine."],"buffs":["Regeneration Potion","Swiftness Potion"],"gear":{"melee":["Copper Shortsword"],"ranged":["Wooden Bow"],"mage":["Aqua Scepter"],"summoner":["Finch Staff"]},"strategy":"King Slime hops toward you and splits into small slimes when hit. He's slow and telegraphed, just keep moving and hitting; there is no real trick to this fight beyond having a weapon better than the Wooden Sword.","unlocks":"A guaranteed Slime armor/accessory drop chance and the Slimy Saddle mount; not required for progression."},{"id":"eye-of-cthulhu","order":2,"era":"Pre-Hardmode","optional":false,"name":"Eye of Cthulhu","summon":"Suspicious Looking Eye","naturalSpawn":"16% chance each midnight once you have 200+ max HP and 3+ NPCs, or use a Suspicious Looking Eye at night.","arena":["A long flat strip at least 60 blocks wide with platforms above it to dodge the charge attacks.","Line it with Campfires and Heart Lanterns for regen."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion"],"gear":{"melee":["Iron Broadsword"],"ranged":["Wooden Bow"],"mage":["Vilethorn"],"summoner":["Finch Staff"]},"strategy":"Two phases: a slow circling approach, then a fast multi-charge dash once below 50% HP. Stand your ground on a flat arena, keep firing, and dodge charges by strafing or hopping onto a platform row.","unlocks":"Nothing progression-gating by itself, but it's the standard first real boss kill and a good gear check before the evil boss."},{"id":"eater-of-worlds","order":3,"era":"Pre-Hardmode","optional":false,"name":"Eater of Worlds","summon":"Worm Food","naturalSpawn":"Use Worm Food in the Corruption (world's evil biome). Skip this entry entirely if your world rolled Crimson, fight Brain of Cthulhu instead.","arena":["Dig a long straight tunnel through the Corruption, it's a giant worm, you want a corridor to hit every segment as it passes."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion"],"gear":{"melee":["Iron Broadsword"],"ranged":["Wooden Bow","Minishark"],"mage":["Vilethorn"],"summoner":["Finch Staff"]},"strategy":"It splits into more worms every time a segment dies, so ranged/piercing weapons that hit multiple segments (Vilethorn) end the fight fastest. Keep running down your tunnel and firing behind you.","unlocks":"Demonite/Crimtane Bars in quantity and Shadow Scales for the Shadow armor set; needed before Skeletron for a comfortable Dungeon kit."},{"id":"brain-of-cthulhu","order":3,"era":"Pre-Hardmode","optional":false,"name":"Brain of Cthulhu","summon":"Bloody Spine","naturalSpawn":"Use a Bloody Spine in the Crimson. Skip this entry if your world rolled Corruption, fight Eater of Worlds instead.","arena":["Clear a wide flat room in the Crimson; the Creepers (its escort adds) need room so you don't get boxed in."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion"],"gear":{"melee":["Iron Broadsword"],"ranged":["Wooden Bow","Minishark"],"mage":["Vilethorn"],"summoner":["Finch Staff"]},"strategy":"Kill the small Creeper orbiting adds first, they heal the Brain if left alone. Once exposed the Brain teleports and charges; a piercing weapon (Vilethorn) hits it through walls and adds alike.","unlocks":"Crimtane Bars and Tissue Samples for Crimson armor; same role as Eater of Worlds for the other evil biome."},{"id":"queen-bee","order":4,"era":"Pre-Hardmode","optional":true,"name":"Queen Bee","summon":"Abeemination","naturalSpawn":"Break a Larva/Bee Hive in the Underground Jungle, or use an Abeemination anywhere.","arena":["A flat corridor near the Hive with platforms for her dive attacks."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion"],"gear":{"melee":["Iron Broadsword"],"ranged":["Minishark"],"mage":["Vilethorn"],"summoner":["Finch Staff"]},"strategy":"Alternates dashing, stinger volleys, and summoning small bees. Keep strafing side to side on a flat strip; her stingers are easy to dodge on foot once you know the pattern.","unlocks":"The Bee Gun, Beenade, Hive Pack (first real summoner setup) and Honey Comb; a strong optional pre-Skeletron detour."},{"id":"skeletron","order":5,"era":"Pre-Hardmode","optional":false,"name":"Skeletron","summon":"Old Man","summonHow":"Talk to the Old Man at the Dungeon entrance at night.","naturalSpawn":"Old Man dialogue only works at night; he becomes the Clothier NPC once Skeletron is defeated.","arena":["Right at the Dungeon entrance, keep it clear of loose Dungeon enemies before you start."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Thorns Potion"],"gear":{"melee":["Blade of Grass","Muramasa"],"ranged":["Minishark","Star Cannon"],"mage":["Demon Scythe","Space Gun"],"summoner":["Imp Staff"]},"strategy":"Its two hands spin around and try to pin you against the arms while the skull charges. Focus the head, not the hands, it's the only part that has to die. Keep moving so you don't get sandwiched.","unlocks":"The Dungeon, permanently. This is the gate before Wall of Flesh, it does not have to happen before the evil boss/Queen Bee."},{"id":"deerclops","order":6,"era":"Pre-Hardmode","optional":true,"name":"Deerclops","summon":"Deerclops Eyeball","naturalSpawn":"Small nightly chance in Snow biome once you have 1 NPC and it's not a Blood Moon; guaranteed with a Deerclops Eyeball at night in Snow.","arena":["Flat ground in the Snow biome; he pounds the ground and throws boulders, keep some horizontal room."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion"],"gear":{"melee":["Blade of Grass","Muramasa"],"ranged":["Star Cannon"],"mage":["Demon Scythe"],"summoner":["Imp Staff"]},"strategy":"A crossover boss (added from Don't Starve). Eye lasers, ground slams, and a boulder throw are the main attacks, all avoidable by strafing. Any pre-Skeletron-tier gear handles him.","unlocks":"Optional, extra pre-Hardmode loot (Eye of the Deerclops-tier weapons and the Deerclops Relic/Trophy/Mask)."},{"id":"wall-of-flesh","order":7,"era":"Pre-Hardmode -> Hardmode","optional":false,"name":"Wall of Flesh","summon":"Guide Voodoo Doll","summonHow":"Throw a Guide Voodoo Doll into lava in The Underworld (the Guide must still be alive elsewhere in the world).","naturalSpawn":"Manual summon only.","arena":["Build a horizontal bridge across the entire Underworld width, this is a running fight, not a standing one.","Clear obstacles like lava pockets and hellforges from the bridge line."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Archery Potion"],"gear":{"melee":["Night's Edge"],"ranged":["Star Cannon","Hellwing Bow"],"mage":["Space Gun","Water Bolt"],"summoner":["Imp Staff"]},"strategy":"It spawns behind you and slowly pushes you across the map, firing lasers, hungry eyes and leeches. Just keep running one direction the whole fight while firing backward; never stop or it catches up.","unlocks":"HARDMODE. This is the single biggest gate in the game: new ores spread everywhere, all enemies get stronger, and the Hallow/an extra Corruption or Crimson stripe appears."},{"id":"queen-slime","order":8,"era":"Early Hardmode","optional":true,"name":"Queen Slime","summon":"Gelatin Crystal","naturalSpawn":"Use a Gelatin Crystal at night in The Hallow.","arena":["Wide flat area in The Hallow with platform rows, she alternates ground combat and an airborne crystal-summon phase."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion"],"gear":{"melee":["Cobalt Sword"],"ranged":["Cobalt Repeater"],"mage":["Crystal Serpent"],"summoner":["Optic Staff"]},"strategy":"Easiest of the early Hardmode bosses; a good gear check right after Wall of Flesh and before the mechanical bosses. Keep strafing and watch for the crystal spikes during her flight phase.","unlocks":"Queen Slime armor/accessories, the Volatile Gelatin summon weapon, and a Hardmode mount (Crystal Slime)."},{"id":"the-twins","order":9,"era":"Hardmode","optional":false,"name":"The Twins","summon":"Mechanical Eye","naturalSpawn":"10-33% chance each night once one mechanical boss is dead; Mechanical Eye works anytime at night.","arena":["Long flat arena with 2-3 platform rows above it; they fly, so vertical room matters as much as horizontal."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion"],"gear":{"melee":["Cobalt Sword","Palladium Sword"],"ranged":["Cobalt Repeater"],"mage":["Crystal Serpent"],"summoner":["Optic Staff"]},"strategy":"Retinazer (laser, ranged) and Spazmatism (fire breath, melee) attack together. Kill Spazmatism first if you're squishy, it closes distance fast; kite along your platforms and focus one twin at a time.","unlocks":"Souls of Sight; needed with the other two mechanical bosses' souls for Hallowed armor and the Ancient Manipulator's follow-on gear."},{"id":"the-destroyer","order":9,"era":"Hardmode","optional":false,"name":"The Destroyer","summon":"Mechanical Worm","naturalSpawn":"Same nightly chance as the other mechanical bosses once one is dead; Mechanical Worm works anytime at night.","arena":["A long straight corridor or open sky arena, it's a giant worm that needs room to snake through."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion"],"gear":{"melee":["Cobalt Sword"],"ranged":["Cobalt Repeater","Minishark"],"mage":["Golden Shower"],"summoner":["Optic Staff"]},"strategy":"Pure DPS race, it doesn't really dodge. Ranged weapons that pierce or a Cobalt Repeater full-auto do the job; stay mobile so its laser-shooting segments can't box you in.","unlocks":"Souls of Might; the easiest of the three mechanical bosses for a ranged build."},{"id":"skeletron-prime","order":9,"era":"Hardmode","optional":false,"name":"Skeletron Prime","summon":"Mechanical Skull","naturalSpawn":"Same nightly chance as the other mechanical bosses once one is dead; Mechanical Skull works anytime at night.","arena":["Flat arena with platforms, his four limbs (cannon, saw, laser, vice-grip head) all have different range, keep distance and moving."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion"],"gear":{"melee":["Cobalt Sword"],"ranged":["Cobalt Repeater"],"mage":["Crystal Serpent"],"summoner":["Optic Staff"]},"strategy":"The hardest of the three mechanical bosses for melee; its saw hand hits hard up close. Ranged/mage from mid-range while dodging the cannon/laser arcs is the safer plan.","unlocks":"Souls of Fright; all three mechanical souls together unlock Hallowed armor and the Ancient Manipulator's Titanium/Adamantite forge follow-ons."},{"id":"plantera","order":10,"era":"Hardmode","optional":false,"name":"Plantera","summon":"Plantera's Bulb","summonHow":"Break a Plantera's Bulb in the Underground Jungle.","naturalSpawn":"The glowing bulb only spawns after all three mechanical bosses are dead; break it to fight her immediately.","arena":["Clear a big room around the bulb in the Jungle itself, don't drag her out of the Jungle or she enrages and hits far harder."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion","Thorns Potion"],"gear":{"melee":["Chlorophyte Saber","Chlorophyte Partisan"],"ranged":["Megashark","Chlorophyte Bullet"],"mage":["Golden Shower","Crystal Serpent"],"summoner":["Blade Staff","Optic Staff"]},"strategy":"Phase 1 she chases and whips tentacles; phase 2 (below 50% HP) she speeds up and spawns homing seeds. Fight in the Jungle so she never enrages, and keep circling so tentacles can't box you in.","unlocks":"The Temple Key, unlocking the Jungle Temple; Seedlings and Thorn Chakram; Chlorophyte spreads more freely after this and the Jungle Temple's Golem fight opens up."},{"id":"golem","order":11,"era":"Hardmode","optional":false,"name":"Golem","summon":"Lihzahrd Power Cell","summonHow":"Place a Lihzahrd Power Cell into a Lihzahrd Altar inside the Jungle Temple.","naturalSpawn":"Manual summon only, requires the Temple Key from Plantera to enter the Jungle Temple at all.","arena":["The Lihzahrd Temple's inner chamber; bring your own platforms, the head detaches and flies once its body is destroyed."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion"],"gear":{"melee":["Chlorophyte Saber","Terra Blade"],"ranged":["Megashark","Piranha Gun"],"mage":["Golden Shower","Rainbow Rod"],"summoner":["Blade Staff","Spider Staff"]},"strategy":"Destroy the arms first if melee (they swing and block hits), or just focus the body at range. Once the body dies the head flies and shoots lasers/spins, keep circling until it's down.","unlocks":"Beetle husks/Turtle shells for Beetle/Turtle armor, and access to the Shimmer-adjacent Lihzahrd loot. Cultists can now be fought at the Dungeon."},{"id":"duke-fishron","order":12,"era":"Hardmode","optional":true,"name":"Duke Fishron","summon":"Truffle Worm","summonHow":"Use a Truffle Worm as bait while fishing in the Ocean.","naturalSpawn":"Manual summon only (fish him up with a Truffle Worm on your hook in the Ocean).","arena":["Open Ocean or sky arena, he's fast and covers huge distances, you want no obstructions at all."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion"],"gear":{"melee":["Terra Blade","Chlorophyte Saber"],"ranged":["Megashark","Piranha Gun"],"mage":["Rainbow Rod"],"summoner":["Blade Staff"]},"strategy":"Widely considered tougher than Plantera/Golem; he alternates a shark-charge phase, a spread-shot phase, and a bubble/tornado phase at low HP. A fast flight mount and constant strafing are close to mandatory.","unlocks":"Endgame accessories (Shrimpy Truffle, Bubble Gun) usable well into the Lunar events; entirely optional for story progression."},{"id":"empress-of-light","order":12,"era":"Hardmode","optional":true,"name":"Empress of Light","summon":"Prismatic Lacewing","summonHow":"Break a Prismatic Lacewing (rainbow butterfly) in The Hallow during the daytime.","naturalSpawn":"The Prismatic Lacewing only spawns in The Hallow after Plantera is dead, in daylight.","arena":["Wide-open sky arena, she is extremely fast and punishes tight spaces; a Nurse nearby you can retreat to helps for first attempts."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion"],"gear":{"melee":["Terra Blade"],"ranged":["Megashark","S.D.M.G."],"mage":["Rainbow Rod","Golden Shower"],"summoner":["Blade Staff","Spider Staff"]},"strategy":"One of the hardest optional fights in the game if fought at night (her behavior changes and gets much more aggressive); fight her in daytime for a fairer pattern of dash/bullet-hell attacks.","unlocks":"Some of the best endgame accessories/wings (Empress Wings) in the game; entirely optional."},{"id":"lunatic-cultist","order":13,"era":"Hardmode -> Endgame","optional":false,"name":"Lunatic Cultist","summon":"Cultist Archer","summonHow":"Kill the 4 Cultist enemies standing at the Dungeon entrance.","naturalSpawn":"The Cultists only appear at the Dungeon entrance after Golem is defeated.","arena":["The Dungeon entrance itself; keep it simple, bring platforms for his teleport/laser phase."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion"],"gear":{"melee":["Terra Blade"],"ranged":["Megashark","S.D.M.G."],"mage":["Rainbow Rod"],"summoner":["Blade Staff","Spider Staff"]},"strategy":"He teleports around casting fireball rings and summoning phantom spectres; watch his cast animation to know which ring pattern is coming and dodge through the gap.","unlocks":"THE CELESTIAL EVENT. Killing him spawns the four Celestial Pillars (Solar, Vortex, Nebula, Stardust) across the map, the last step before Moon Lord."},{"id":"celestial-pillars","order":14,"era":"Endgame","optional":false,"name":"Celestial Pillars (Solar, Vortex, Nebula, Stardust)","summon":"","summonHow":"Spawns automatically after Lunatic Cultist dies.","naturalSpawn":"All four appear at once; you can fight them in any order.","arena":["Each Pillar has its own shield that only drops once enough of its themed enemies die nearby; fight in the open with an escape route, these are event-scale enemy waves, not single bosses."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion","Endurance Potion"],"gear":{"melee":["Terra Blade"],"ranged":["Megashark","S.D.M.G."],"mage":["Rainbow Rod","Laser Machinegun"],"summoner":["Blade Staff","Spider Staff"]},"strategy":"Solar (melee enemies, hits hardest), Vortex (ranged enemies), Nebula (mage enemies, drops buffs when you kill its adds), Stardust (summons, splits into more enemies). Bring a build that counters each pillar's enemy type.","unlocks":"Luminite and Fragments (Solar/Vortex/Nebula/Stardust) for the four endgame armor sets and weapons, and it opens the ability to summon Moon Lord."},{"id":"moon-lord","order":15,"era":"Endgame","optional":false,"name":"Moon Lord","summon":"Celestial Sigil","naturalSpawn":"Manual summon only, crafted from Fragments after clearing all four Celestial Pillars.","arena":["Wide-open sky arena with Honey/regen setups, Bewitching Table + Sharpening Station, and a full row of platforms; this is the final fight, treat it like one."],"buffs":["Regeneration Potion","Swiftness Potion","Ironskin Potion","Wrath Potion","Endurance Potion","Rage Potion"],"gear":{"melee":["Terra Blade","Star Wrath"],"ranged":["S.D.M.G.","Megashark"],"mage":["Last Prism","Rainbow Rod"],"summoner":["Blade Staff","Spider Staff"]},"strategy":"Destroy the two hands first to stop the most dangerous close-range attacks, then focus the eye/head. His true-damage lasers and Phantasmal Death Ray ignore defense, so dodging matters more than armor here.","unlocks":"Luminite Bars for the best gear in the game, and completes the vanilla main progression."}];
